DROP TABLE IF EXISTS `call_tree_members`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `call_tree_members` (
  `call_tree_member_id` bigint NOT NULL AUTO_INCREMENT,
  `member_name` varchar(200) NOT NULL,
  `member_email` varchar(320) NOT NULL,
  `phone_number` varchar(50) NOT NULL,
  `sequence_number` int DEFAULT NULL,
  `escalation_level` int DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `employee_id` bigint DEFAULT NULL,
  `call_tree_run_id` bigint NOT NULL,
  `cmsc_member_id` bigint DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `reached_channel` varchar(20) NOT NULL,
  `reached_flag` tinyint(1) NOT NULL,
  PRIMARY KEY (`call_tree_member_id`),
  KEY `idx_ctm_run` (`call_tree_run_id`),
  KEY `call_tree_members_employee_id_d1d0e1cd_fk_employees_employee_id` (`employee_id`),
  KEY `call_tree_members_cmsc_member_id_83525264_fk_cmsc_memb` (`cmsc_member_id`),
  CONSTRAINT `call_tree_members_call_tree_run_id_32baa9a7_fk_call_tree` FOREIGN KEY (`call_tree_run_id`) REFERENCES `call_tree_runs` (`call_tree_run_id`),
  CONSTRAINT `call_tree_members_cmsc_member_id_83525264_fk_cmsc_memb` FOREIGN KEY (`cmsc_member_id`) REFERENCES `cmsc_members` (`cmsc_member_id`),
  CONSTRAINT `call_tree_members_employee_id_d1d0e1cd_fk_employees_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`employee_id`)
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
