--
-- Table structure for table `call_tree_runs`
--

DROP TABLE IF EXISTS `call_tree_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `call_tree_runs` (
  `call_tree_run_id` bigint NOT NULL AUTO_INCREMENT,
  `broadcast_id` varchar(100) NOT NULL,
  `call_tree_type` varchar(80) NOT NULL,
  `started_at` datetime(6) DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `status` varchar(50) NOT NULL,
  `simulation_flag` tinyint(1) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `center_id` bigint DEFAULT NULL,
  `cost_code_id` bigint DEFAULT NULL,
  `plan_version_id` bigint DEFAULT NULL,
  `process_id` bigint DEFAULT NULL,
  `initiated_by` bigint DEFAULT NULL,
  `providers_enabled` json NOT NULL DEFAULT (_utf8mb4'{}'),
  PRIMARY KEY (`call_tree_run_id`),
  KEY `call_tree_runs_center_id_b37e1f39_fk_centers_center_id` (`center_id`),
  KEY `call_tree_runs_plan_version_id_39213f69_fk_plan_vers` (`plan_version_id`),
  KEY `call_tree_runs_process_id_ce156ca3_fk_processes_process_id` (`process_id`),
  KEY `call_tree_runs_initiated_by_56387484_fk_user_accounts_user_id` (`initiated_by`),
