DROP TABLE IF EXISTS `coordinator_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `coordinator_assignments` (
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `active_flag` tinyint(1) NOT NULL,
  `coordinator_assignment_id` bigint NOT NULL AUTO_INCREMENT,
  `coordinator_type` varchar(80) NOT NULL,
  `additional_user_flag` tinyint(1) NOT NULL,
  `employee_id` bigint NOT NULL,
  `estate_id` bigint DEFAULT NULL,
  `plan_version_id` bigint NOT NULL,
  PRIMARY KEY (`coordinator_assignment_id`),
  UNIQUE KEY `uq_coordinator_assignment` (`plan_version_id`,`employee_id`,`coordinator_type`),
  KEY `coordinator_assignme_employee_id_ed374141_fk_employees` (`employee_id`),
  KEY `coordinator_assignments_estate_id_92bfd4af_fk_estates_estate_id` (`estate_id`),
  KEY `coordinator_assignments_active_flag_1a027265` (`active_flag`),
  CONSTRAINT `coordinator_assignme_employee_id_ed374141_fk_employees` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`employee_id`),
  CONSTRAINT `coordinator_assignme_plan_version_id_6f3c9917_fk_plan_vers` FOREIGN KEY (`plan_version_id`) REFERENCES `plan_versions` (`plan_version_id`),
  CONSTRAINT `coordinator_assignments_estate_id_92bfd4af_fk_estates_estate_id` FOREIGN KEY (`estate_id`) REFERENCES `estates` (`estate_id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
