--
-- Table structure for table `notification_log`
--

DROP TABLE IF EXISTS `notification_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_log` (
  `notification_log_id` bigint NOT NULL AUTO_INCREMENT,
  `event_type` varchar(50) NOT NULL,
  `entity_type` varchar(80) NOT NULL,
  `entity_id` bigint DEFAULT NULL,
  `to_email` varchar(320) NOT NULL,
  `cc_emails` longtext NOT NULL,
  `subject` varchar(500) NOT NULL,
  `template_name` varchar(150) NOT NULL,
  `context` json DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `error_detail` longtext NOT NULL,
  `attempts` smallint unsigned NOT NULL,
  `sent_at` datetime(6) DEFAULT NULL,
  `idempotency_key` varchar(255) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `recipient_user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`notification_log_id`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `notification_log_recipient_user_id_7f2f95df_fk_user_acco` (`recipient_user_id`),
  KEY `idx_notif_entity` (`entity_type`,`entity_id`),
  KEY `idx_notif_status` (`status`,`created_at`),
  CONSTRAINT `notification_log_recipient_user_id_7f2f95df_fk_user_acco` FOREIGN KEY (`recipient_user_id`) REFERENCES `user_accounts` (`user_id`),
  CONSTRAINT `notification_log_chk_1` CHECK ((`attempts` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=208 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

