--
-- Table structure for table `plan_versions`
--

DROP TABLE IF EXISTS `plan_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `plan_versions` (
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `plan_version_id` bigint NOT NULL AUTO_INCREMENT,
  `legacy_id` bigint DEFAULT NULL,
  `version_number` int NOT NULL,
  `plan_mode` varchar(50) NOT NULL,
  `review_mode` varchar(50) NOT NULL,
  `status` varchar(50) NOT NULL,
  `published_flag` tinyint(1) NOT NULL,
  `copied_flag` tinyint(1) NOT NULL,
  `approved_at` datetime(6) DEFAULT NULL,
  `approved_by` bigint DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `plan_id` bigint NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`plan_version_id`),
  UNIQUE KEY `uq_plan_version_number` (`plan_id`,`version_number`),
  UNIQUE KEY `legacy_id` (`legacy_id`),
  KEY `idx_pv_status_pub` (`status`,`published_flag`),
  KEY `idx_pv_plan_version` (`plan_id`,`version_number` DESC),
  KEY `plan_versions_approved_by_4bcaf76d_fk_user_accounts_user_id` (`approved_by`),
  KEY `plan_versions_created_by_fc0b670f_fk_user_accounts_user_id` (`created_by`),
  KEY `plan_versions_updated_by_aba5177d_fk_user_accounts_user_id` (`updated_by`),
  CONSTRAINT `plan_versions_approved_by_4bcaf76d_fk_user_accounts_user_id` FOREIGN KEY (`approved_by`) REFERENCES `user_accounts` (`user_id`),
  CONSTRAINT `plan_versions_created_by_fc0b670f_fk_user_accounts_user_id` FOREIGN KEY (`created_by`) REFERENCES `user_accounts` (`user_id`),
  CONSTRAINT `plan_versions_plan_id_00a96e82_fk_plans_plan_id` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`plan_id`),
  CONSTRAINT `plan_versions_updated_by_aba5177d_fk_user_accounts_user_id` FOREIGN KEY (`updated_by`) REFERENCES `user_accounts` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

