DROP TABLE IF EXISTS `risks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `risks` (
  `risk_id` bigint NOT NULL AUTO_INCREMENT,
  `resource_type` varchar(100) NOT NULL,
  `risk_name` varchar(255) NOT NULL,
  `description` longtext NOT NULL,
  `impact_area` varchar(150) NOT NULL,
  `likelihood_rating` decimal(5,2) DEFAULT NULL,
  `severity_rating` decimal(5,2) DEFAULT NULL,
  `control_effectiveness_rating` decimal(5,2) DEFAULT NULL,
  `inherent_risk_score` decimal(10,2) DEFAULT NULL,
  `residual_risk_score` decimal(10,2) DEFAULT NULL,
  `risk_level` varchar(50) NOT NULL,
  `target_closure_date` date DEFAULT NULL,
  `occurred_flag` tinyint(1) DEFAULT NULL,
  `comments` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `owner_employee_id` bigint DEFAULT NULL,
  `plan_version_id` bigint NOT NULL,
  PRIMARY KEY (`risk_id`),
  KEY `risks_owner_employee_id_1fc81151_fk_employees_employee_id` (`owner_employee_id`),
  KEY `risks_plan_version_id_b99c4159_fk_plan_versions_plan_version_id` (`plan_version_id`),
  CONSTRAINT `risks_owner_employee_id_1fc81151_fk_employees_employee_id` FOREIGN KEY (`owner_employee_id`) REFERENCES `employees` (`employee_id`),
  CONSTRAINT `risks_plan_version_id_b99c4159_fk_plan_versions_plan_version_id` FOREIGN KEY (`plan_version_id`) REFERENCES `plan_versions` (`plan_version_id`)
) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
